using System.ComponentModel.DataAnnotations;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.AspNetCore.Mvc.Rendering;using Microsoft.EntityFrameworkCore;using NoryMusicLMS_VS.Data;using NoryMusicLMS_VS.Models;using NoryMusicLMS_VS.Services;
namespace NoryMusicLMS_VS.Areas.Admin.Pages.Lessons;
[Authorize(Roles="Admin")] public class CreateModel:PageModel{private readonly ApplicationDbContext _db;private readonly ImageStorageService _images;public CreateModel(ApplicationDbContext db,ImageStorageService images){_db=db;_images=images;}[BindProperty]public LessonInput Input{get;set;}=new();public class LessonInput{[Required]public int CourseId{get;set;}[Required,StringLength(100)]public string Title{get;set;}="";[StringLength(2000)]public string Content{get;set;}="";[Range(1,1000)]public int OrderIndex{get;set;}=1;[Url]public string? VideoUrl{get;set;}[Url]public string? AudioUrl{get;set;}[Url]public string? NotationUrl{get;set;}public IFormFile? Image{get;set;}}public async Task<IActionResult> OnGetAsync(){await LoadCoursesAsync();return Page();}public async Task<IActionResult> OnPostAsync(){if(!await _db.Courses.AnyAsync(c=>c.Id==Input.CourseId&&c.IsActive))ModelState.AddModelError("Input.CourseId","Select an active course.");if(ImageStorageService.Validate(Input.Image) is{ }e)ModelState.AddModelError("Input.Image",e);if(!ModelState.IsValid){await LoadCoursesAsync();return Page();}var url=await _images.ApplyAsync(null,Input.Image,false,null);_db.Lessons.Add(new Lesson{CourseId=Input.CourseId,Title=Input.Title.Trim(),Content=Input.Content.Trim(),OrderIndex=Input.OrderIndex,VideoUrl=Input.VideoUrl,AudioUrl=Input.AudioUrl,NotationUrl=Input.NotationUrl,ImageUrl=url,CreatedAt=DateTime.UtcNow});await _db.SaveChangesAsync();TempData["StatusMessage"]="Lesson created.";return RedirectToPage("./Index");}private async Task LoadCoursesAsync()=>ViewData["CourseId"]=new SelectList(await _db.Courses.Where(c=>c.IsActive).OrderBy(c=>c.Title).ToListAsync(),"Id","Title",Input.CourseId);}
